	/** 
	 * jumpstart the process by instantiating2 Position
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		positionId = PositionService.getPositionInstance()
		.createPosition( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PositionService.getPositionInstance()
				.createPosition( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.positionSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Position : " + successValue.getPositionId());
							  if (successValue.getPositionId().equals(positionId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPositionList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Position test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on position consumed")
					);
			subscriber.positionSubscribe( positionId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Position : " + successValue.getPositionId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPositionList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on position for positionId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Position. 
	 */
	protected Position read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Position" );

		Position entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Position with primary key" );
		msg.append( positionId );
		
		PositionFetchOneSummary fetchOneSummary = new PositionFetchOneSummary( positionId );

		try {
			entity = PositionService.getPositionInstance().getPosition( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Position " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Position.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Position." );

		StringBuilder msg = new StringBuilder( "Failed to update a Position : " );        
		Position entity = read();
		UpdatePositionCommand command = generateUpdateCommand();
		command.setPositionId(entity.getPositionId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Position." );

			// for use later on...
			positionId = entity.getPositionId();

			PositionService proxy = PositionService.getPositionInstance();  

			proxy.updatePosition( command ).get();

			LOGGER.info( "-- Successfully saved Position - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + positionId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Position.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Position." );

		Position entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Position with id " + positionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Position with id " + positionId );

			throw e;
		}

		try{
			PositionService.getPositionInstance().delete( new DeletePositionCommand( entity.getPositionId() ) ).get();
			LOGGER.info( "-- Successfully deleted Position with id " + positionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Position with id " + positionId );

			throw e;
		}
	}

	/**
	 * get all Positions.
	 */
	protected List<Position> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Positions:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Position : " );        
		List<Position> collection  = new ArrayList<>();

		try {
			// call the static get method on the PositionService
			collection = PositionService.getPositionInstance().getAllPosition();
			assertNotNull( collection, "An Empty collection of Position was incorrectly returned.");
			
			// Now print out the values
			Position entity = null;            
			Iterator<Position> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPositionId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

